select pg_temp.assert_true((select count(*)=31 and bool_and(relrowsecurity and relforcerowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and relkind='r'), 'all 31 application tables enforce RLS');
select pg_temp.assert_true((select count(*)=8 from public.lessons where language='English' and content_origin='original_practice'), 'eight original English lessons');
select pg_temp.assert_true((select count(*)=8 from public.assessments), 'one checkpoint per original lesson');
select pg_temp.assert_true((select count(*)=14 from public.academic_grades), 'both boards support Grades 4–10');
select pg_temp.assert_true((select array_agg(distinct g.number order by g.number)=array[6,7,8,10]::smallint[] from public.lessons l join public.chapters c on c.id=l.chapter_id join public.academic_subjects s on s.id=c.subject_id join public.academic_grades g on g.id=s.grade_id), 'no fabricated gap-grade lessons');
select pg_temp.assert_true((select count(*)=2 from public.curriculum_sources), 'provenance is separate from original content');
select pg_temp.expect_error($q$insert into public.academic_grades values ('bad','cbse',11,false,now(),now())$q$,'23514','learner Grade 11 rejected');
select pg_temp.expect_error($q$insert into public.academic_grades values ('bad','cbse',3,false,now(),now())$q$,'23514','learner Grade 3 rejected');
select pg_temp.expect_error($q$insert into public.academic_subjects(id,grade_id,name) values ('bad','missing','Mathematics')$q$,'23503','subject cannot reference unknown grade');
select pg_temp.expect_error($q$update public.chapters set subject_id='missing' where id='cbse-8-math-linear-equations'$q$,'23503','chapter parent enforced');
select pg_temp.expect_error($q$update public.lessons set chapter_id='missing' where id='equations'$q$,'23503','lesson parent enforced');
select pg_temp.expect_error($q$update public.assessments set answer_index=99 where id='equations-checkpoint'$q$,'23514','assessment answer bounds');
select pg_temp.expect_error($q$update public.assessments set lesson_id='missing' where id='equations-checkpoint'$q$,'23503','assessment lesson enforced');
select pg_temp.expect_error($q$insert into public.assessment_attempts(learner_id,assessment_id,lesson_id,selected_option,score_percent) values ('00000000-0000-0000-0000-000000000001','equations-checkpoint','fractions',0,100)$q$,'23503','attempt cannot pair assessment with wrong lesson');
select pg_temp.expect_error($q$insert into public.assessment_attempts(learner_id,assessment_id,lesson_id,selected_option,score_percent) values ('00000000-0000-0000-0000-000000000001','equations-checkpoint','equations',9,100)$q$,'23514','attempt option bounds');
select pg_temp.expect_error($q$insert into public.lesson_progress(learner_id,lesson_id) values ('00000000-0000-0000-0000-000000000001','equations')$q$,'23505','progress unique per learner and lesson');
select pg_temp.expect_error($q$update public.lesson_progress set checkpoint_percent=101$q$,'23514','progress bounds');
select pg_temp.expect_error($q$insert into public.learner_bookmarks(learner_id,lesson_id) values ('00000000-0000-0000-0000-000000000001','equations')$q$,'23505','bookmark primary key prevents duplicates');
select pg_temp.expect_error($q$insert into public.tutor_profiles(user_id,academic_grade) values ('00000000-0000-0000-0000-000000000001',11)$q$,'23503','learner cannot be a tutor without trusted role');
select pg_temp.assert_true((select max(academic_grade)=12 from public.tutor_profiles), 'tutor Grades 11 and 12 remain supported');
select pg_temp.expect_error($q$insert into public.tutor_availability(tutor_id,weekday,starts_at,ends_at) values ('00000000-0000-0000-0000-000000000003',9,'18:00','17:00')$q$,'23514','availability bounds');
select pg_temp.expect_error($q$insert into public.tutor_verification_records(tutor_id,status,reviewed_by,verified_grade,decision_note) values ('00000000-0000-0000-0000-000000000003','approved','00000000-0000-0000-0000-000000000003',11,'self approval')$q$,'23514','even trusted writes cannot record self-verification');

select pg_temp.expect_error($q$insert into public.learner_academic_enrollments(learner_id,subject_id,language,is_active) values ('00000000-0000-0000-0000-000000000001','cbse-8-mathematics','English',true),('00000000-0000-0000-0000-000000000001','cbse-6-mathematics','English',true)$q$,'23505','unique index still forbids two active enrollments');
